// Parse AI Agent output into structured JSON for the frontend without any limit
const output = String($input.first().json.output || '');
// Grabs the raw text output from the AI Agent node

let results = [];
try {
  const jsonMatch = output.match(/\[[\s\S]*\]/);
  if (jsonMatch) {
    results = JSON.parse(jsonMatch[0]);
  } else {
    results = [{ "Response": output }];
  }

  results = results.map(item => {
    const size = String(item["Size"] || "").trim().toLowerCase();
    const rating = parseFloat(item["Customer Rating"]);
    let leadScore = "Low";

    if (!isNaN(rating)) {
      // Rating exists — score using Size + Rating together
      if (size === "enterprise" && rating >= 4.0) {
        leadScore = "High";
      } else if (
        size === "medium" ||
        (size === "enterprise" && rating < 4.0) ||
        (rating >= 3.0 && rating < 4.0)
      ) {
        leadScore = "Medium";
      } else if (size === "smb" || rating < 3.0) {
        leadScore = "Low";
      }
    } else {
      // No rating available (N/A) — fall back to Size-only scoring
      if (size === "enterprise") {
        leadScore = "Medium";
      } else if (size === "medium") {
        leadScore = "Medium";
      } else {
        leadScore = "Low";
      }
    }

    return { ...item, "Lead Score": leadScore };
  });

} catch (e) {
  results = [{ "Response": output }];
}

return [{ json: { success: true, agent: "Lead Discovery", resultsCount: results.length, results: results } }];
